"""Score a router on labelled sentences (nothing is sent to the TV): eval/utterances.jsonl (107, quick; the panel's
"Run tests") or eval/commands.jsonl (654 generated by eval/build_commands.py, with categories and a held-out "test"
split)."""
import json
import statistics
import time
from pathlib import Path

EVAL_DIR = Path(__file__).resolve().parents[3] / "eval"
EVAL_FILE = EVAL_DIR / "utterances.jsonl"


def matches(action, expect: dict) -> bool:
    got = action.model_dump()
    for key, want in expect.items():
        have = got.get(key)
        if isinstance(want, str) and isinstance(have, str):
            if want.lower().strip() != have.lower().strip():
                return False
        elif have != want:
            return False
    return True


async def run(router, path: Path = EVAL_FILE, split: str | None = None) -> dict:
    rows = [json.loads(line) for line in path.read_text().splitlines() if line.strip()]
    rows = [r for r in rows if split is None or r.get("split") == split]
    intent_ok = full_ok = 0
    results, by_via = [], {}
    for row in rows:
        t = time.perf_counter()
        d = await router.decide(row["text"])
        ms = (time.perf_counter() - t) * 1000
        by_via.setdefault(d.via, []).append(ms)
        i_ok = d.action.type == row["expect"]["type"]
        f_ok = i_ok and matches(d.action, row["expect"])
        intent_ok += i_ok
        full_ok += f_ok
        results.append({"text": row["text"], "expect": row["expect"], "ok": f_ok, "via": d.via, "rule": d.rule,
                        "cat": row.get("cat", ""),
                        "confidence": round(d.confidence, 2),
                        "got": {k: v for k, v in d.action.model_dump().items() if v not in (None, False, "")}})
    timing = {}
    for via, xs in by_via.items():
        xs.sort()
        timing[via] = {"n": len(xs), "p50": statistics.median(xs), "p95": xs[int(0.95 * (len(xs) - 1))]}
    return {"n": len(rows), "intent_ok": intent_ok, "full_ok": full_ok, "results": results, "timing": timing}
